codeExample:
const user = {
  name: 'Alice',
  // Normal function: 'this' refers to the object calling it (user)
  greet: function() {
    console.log(`Hello, my name is ${this.name}`);
  },
  // Arrow function: 'this' is inherited from the outer scope (Global)
  greetArrow: () => {
    console.log(`Arrow says: my name is ${this.name}`);
  }
};

user.greet(); // "Hello, my name is Alice"
user.greetArrow(); // "Arrow says: my name is undefined"

// Losing 'this' context
const unboundGreet = user.greet;
unboundGreet(); // "Hello, my name is undefined" (or throws error in strict mode)

// Fixing it with bind
const boundGreet = user.greet.bind(user);
boundGreet(); // "Hello, my name is Alice"
